:root {
  --background: #ffffff;
  --foreground: #171717;
}
@media (prefers-color-scheme: dark) {
  :root {
    --background: #0a0a0a;
    --foreground: #ededed;
  }
}
body {
  background: var(--background);
  color: var(--foreground);
  font-family: Arial, Helvetica, sans-serif;
  letter-spacing: 0.02em;
}
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 100px;
}
::-webkit-scrollbar-thumb {
  background: rgba(156, 163, 175, 0.4);
  border-radius: 100px;
  transition: background 0.2s ease;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(156, 163, 175, 0.6);
}
.dark ::-webkit-scrollbar-thumb {
  background: rgba(75, 85, 99, 0.5);
}
.dark ::-webkit-scrollbar-thumb:hover {
  background: rgba(75, 85, 99, 0.7);
}
.midnight {
  --midnight-glow: #00d4ff;
  --midnight-border: rgba(6, 182, 212, 0.2);
}
.midnight * {
  scrollbar-color: rgba(6, 182, 212, 0.3) transparent;
}
.midnight ::-webkit-scrollbar-thumb {
  background: rgba(6, 182, 212, 0.3);
}
.midnight ::-webkit-scrollbar-thumb:hover {
  background: rgba(6, 182, 212, 0.5);
}
.purple {
  --purple-glow: #ff00ff;
  --purple-border: rgba(236, 72, 153, 0.2);
}
.purple * {
  scrollbar-color: rgba(236, 72, 153, 0.3) transparent;
}
.purple ::-webkit-scrollbar-thumb {
  background: rgba(236, 72, 153, 0.3);
}
.purple ::-webkit-scrollbar-thumb:hover {
  background: rgba(236, 72, 153, 0.5);
}
html {
  scroll-behavior: smooth;
}
nav::-webkit-scrollbar {
  width: 6px;
}
nav::-webkit-scrollbar-thumb {
  background: rgba(156, 163, 175, 0.3);
  border-radius: 100px;
}
nav::-webkit-scrollbar-thumb:hover {
  background: rgba(156, 163, 175, 0.5);
}
.dark nav::-webkit-scrollbar-thumb {
  background: rgba(75, 85, 99, 0.4);
}
.dark nav::-webkit-scrollbar-thumb:hover {
  background: rgba(75, 85, 99, 0.6);
}
.midnight nav::-webkit-scrollbar-thumb {
  background: rgba(6, 182, 212, 0.25);
}
.midnight nav::-webkit-scrollbar-thumb:hover {
  background: rgba(6, 182, 212, 0.4);
}
.purple nav::-webkit-scrollbar-thumb {
  background: rgba(236, 72, 153, 0.25);
}
.purple nav::-webkit-scrollbar-thumb:hover {
  background: rgba(236, 72, 153, 0.4);
}
